head.b:skin:
/*
 * AI Forge - Production Ready Blogger Theme
 * Niche: Artificial Intelligence
 * Author: Jules (AI Forge Dev Team)
 */

/* --- THEME CONTROL PANEL --- */
/* <Group description="AI Forge Colors" title="Brand Colors">
    <Variable name="bg.main" description="Main Background" type="color" default="#0B0F19"/>
    <Variable name="bg.secondary" description="Secondary Background" type="color" default="#111827"/>
    <Variable name="accent.primary" description="Primary Accent (Neon)" type="color" default="#00F5A0"/>
    <Variable name="accent.secondary" description="Secondary Accent (Indigo)" type="color" default="#4F46E5"/>
    <Variable name="text.main" description="Primary Text" type="color" default="#E5E7EB"/>
    <Variable name="text.muted" description="Muted Text" type="color" default="#9CA3AF"/>
</Group>
<Group description="Theme Features" title="Toggles">
    <Variable name="anim.enable" description="Enable Animations" type="string" default="true"/>
    <Variable name="sound.enable" description="Enable Sound Effects" type="string" default="false"/>
    <Variable name="posts.per.section" description="Posts per section" type="number" default="6"/>
</Group> */

:root {
    --bg-main: #0B0F19;
    --bg-secondary: #111827;
    --accent-primary: #00F5A0;
    --accent-secondary: #4F46E5;
    --text-main: #E5E7EB;
    --text-muted: #9CA3AF;
    --glass: rgba(255, 255, 255, 0.03);
    --glass-border: rgba(255, 255, 255, 0.08);
    --neon-glow: 0 0 15px rgba(0, 245, 160, 0.3);
    --transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Global Reset */
* { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
    background-color: var(--bg-main);
    color: var(--text-main);
    font-family: 'Inter', sans-serif;
    line-height: 1.6;
    overflow-x: hidden;
    -webkit-font-smoothing: antialiased;
}

/* Animations */
@keyframes fadeIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
@keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
@keyframes pulse { 0% { box-shadow: 0 0 0 0 rgba(0, 245, 160, 0.4); } 70% { box-shadow: 0 0 0 10px rgba(0, 245, 160, 0); } 100% { box-shadow: 0 0 0 0 rgba(0, 245, 160, 0); } }
@keyframes progress { from { width: 0%; } to { width: 100%; } }
@keyframes meshGradient {
    0% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
    100% { background-position: 0% 50%; }
}

.reveal { opacity: 0; transition: var(--transition); }
.reveal.active { opacity: 1; transform: translateY(0); }

/* Sticky Header */
header {
    position: fixed; top: 0; width: 100%; z-index: 1000;
    background: rgba(11, 15, 25, 0.8);
    backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--glass-border);
    transition: var(--transition);
}
header.scrolled { padding: 5px 0; background: rgba(11, 15, 25, 0.95); }

.nav-container {
    max-width: 1300px; margin: 0 auto; padding: 15px 25px;
    display: flex; justify-content: space-between; align-items: center;
}

.logo-wrap { display: flex; align-items: center; text-decoration: none; gap: 10px; }
.logo-text { font-weight: 800; font-size: 1.5rem; color: #fff; letter-spacing: -1px; }
.logo-text span { color: var(--accent-primary); }

nav ul { display: flex; list-style: none; gap: 25px; }
nav a { color: var(--text-main); text-decoration: none; font-size: 0.9rem; font-weight: 500; transition: var(--transition); opacity: 0.8; }
nav a:hover { color: var(--accent-primary); opacity: 1; }

/* Reading Progress */
.progress-container { position: fixed; top: 0; width: 100%; height: 3px; z-index: 1001; }
.progress-bar { height: 100%; background: linear-gradient(to right, var(--accent-secondary), var(--accent-primary)); width: 0%; }

/* Hero Section */
.hero {
    height: 85vh; min-height: 600px;
    display: flex; align-items: center; justify-content: center;
    text-align: center; position: relative; overflow: hidden;
    background: radial-gradient(circle at 50% 50%, rgba(79, 70, 229, 0.15), transparent 70%);
}
.hero::before {
    content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
    background: linear-gradient(-45deg, #0B0F19, #111827, #0B0F19, #1a1a2e);
    background-size: 400% 400%; animation: meshGradient 15s ease infinite;
    z-index: -1;
}
.hero-content { max-width: 800px; padding: 0 20px; z-index: 2; }
.hero h1 { font-size: clamp(2.5rem, 8vw, 4.5rem); font-weight: 800; line-height: 1.1; margin-bottom: 20px; }
.hero h1 span { color: var(--accent-primary); text-shadow: var(--neon-glow); }
.hero p { font-size: 1.2rem; color: var(--text-muted); margin-bottom: 35px; }

/* Buttons */
.btn {
    display: inline-flex; align-items: center; gap: 10px;
    padding: 14px 30px; border-radius: 50px; font-weight: 600;
    text-decoration: none; transition: var(--transition); cursor: pointer; border: none;
}
.btn-primary {
    background: var(--accent-primary); color: var(--bg-main);
    box-shadow: var(--neon-glow);
}
.btn-primary:hover { transform: translateY(-3px); box-shadow: 0 8px 25px rgba(0, 245, 160, 0.5); }
.btn-glass {
    background: var(--glass); color: #fff;
    border: 1px solid var(--glass-border); backdrop-filter: blur(5px);
}
.btn-glass:hover { background: rgba(255,255,255,0.1); transform: translateY(-3px); }

/* Card System */
.section-title { font-size: 2rem; font-weight: 700; margin-bottom: 30px; display: flex; align-items: center; gap: 15px; }
.section-title::after { content: ''; flex-grow: 1; height: 1px; background: var(--glass-border); }

.card-grid {
    display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 25px; margin-bottom: 60px;
}

.post-card {
    background: var(--bg-secondary);
    border-radius: 20px; border: 1px solid var(--glass-border);
    overflow: hidden; text-decoration: none; transition: var(--transition);
    display: flex; flex-direction: column; position: relative;
}
.post-card:hover {
    transform: translateY(-10px);
    border-color: var(--accent-primary);
    box-shadow: 0 20px 40px rgba(0,0,0,0.4);
}
.card-img {
    width: 100%; height: 200px; object-fit: cover;
    transition: var(--transition); filter: brightness(0.9);
}
.post-card:hover .card-img { transform: scale(1.05); filter: brightness(1.1); }

.card-body { padding: 25px; flex-grow: 1; display: flex; flex-direction: column; }
.card-tag { font-size: 0.7rem; font-weight: 700; color: var(--accent-primary); text-transform: uppercase; margin-bottom: 10px; }
.card-title { font-size: 1.25rem; font-weight: 700; color: #fff; margin-bottom: 12px; line-height: 1.4; }
.card-excerpt { font-size: 0.9rem; color: var(--text-muted); margin-bottom: 20px; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.card-footer { margin-top: auto; display: flex; justify-content: space-between; align-items: center; border-top: 1px solid var(--glass-border); padding-top: 15px; }
.read-more { font-size: 0.85rem; font-weight: 600; color: var(--accent-primary); display: flex; align-items: center; gap: 5px; }

/* Skeleton Loading */
.skeleton { background: linear-gradient(90deg, var(--bg-secondary) 25%, #1f2937 50%, var(--bg-secondary) 75%); background-size: 200% 100%; animation: meshGradient 1.5s infinite; }

/* Main Container */
.main-wrapper { max-width: 1300px; margin: 80px auto; padding: 0 25px; display: grid; grid-template-columns: 1fr 320px; gap: 40px; }
.full-width { grid-column: 1 / -1; }

/* Sidebar */
.sidebar-widget { background: var(--bg-secondary); border-radius: 20px; padding: 25px; margin-bottom: 30px; border: 1px solid var(--glass-border); }
.widget-title { font-size: 1.1rem; font-weight: 700; margin-bottom: 20px; color: var(--accent-primary); }

/* Footer */
footer { background: #070a11; border-top: 1px solid var(--glass-border); padding: 80px 25px 40px; }
.footer-grid { max-width: 1300px; margin: 0 auto; display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 40px; margin-bottom: 60px; }
.footer-brand h2 { font-size: 1.8rem; margin-bottom: 15px; }
.footer-brand p { color: var(--text-muted); font-size: 0.9rem; }
.footer-links h4 { margin-bottom: 20px; font-weight: 600; }
.footer-links ul { list-style: none; }
.footer-links li { margin-bottom: 12px; }
.footer-links a { color: var(--text-muted); text-decoration: none; font-size: 0.9rem; transition: var(--transition); }
.footer-links a:hover { color: var(--accent-primary); padding-left: 5px; }
.footer-bottom { border-top: 1px solid var(--glass-border); padding-top: 30px; text-align: center; color: var(--text-muted); font-size: 0.85rem; }

/* Post Content */
.post-header { margin-bottom: 40px; text-align: center; }
.post-header h1 { font-size: 3rem; margin-bottom: 20px; }
.post-meta { display: flex; justify-content: center; gap: 20px; font-size: 0.9rem; color: var(--text-muted); }
.post-body { font-size: 1.1rem; line-height: 1.8; color: #d1d5db; }
.post-body img { max-width: 100%; border-radius: 20px; margin: 30px 0; }
.post-body h2, .post-body h3 { color: #fff; margin: 40px 0 20px; }

/* Sound Toggle */
.sound-toggle { position: fixed; bottom: 30px; left: 30px; background: var(--bg-secondary); border: 1px solid var(--glass-border); width: 45px; height: 45px; border-radius: 50%; display: flex; align-items: center; justify-content: center; cursor: pointer; z-index: 100; transition: var(--transition); }
.sound-toggle:hover { border-color: var(--accent-primary); color: var(--accent-primary); }

/* Responsive */
@media (max-width: 1024px) {
    .main-wrapper { grid-template-columns: 1fr; }
    .hero h1 { font-size: 3.5rem; }
}
@media (max-width: 768px) {
    nav { display: none; }
    .hero h1 { font-size: 2.8rem; }
    .post-header h1 { font-size: 2.2rem; }
}

/* Reading Time & Share */
.reading-time { font-style: italic; opacity: 0.7; }
.back-to-top { position: fixed; bottom: 30px; right: 30px; background: var(--accent-primary); color: var(--bg-main); width: 45px; height: 45px; border-radius: 50%; display: flex; align-items: center; justify-content: center; cursor: pointer; z-index: 100; transition: var(--transition); opacity: 0; visibility: hidden; box-shadow: var(--neon-glow); }
.back-to-top.show { opacity: 1; visibility: visible; }

body.script:
//
    /* AI Forge Core Script */
    const config = {
        soundEnabled: false,
        postsPerSection: 3
    };

    // Scroll Progress Bar
    window.onscroll = function() {
        let winScroll = document.body.scrollTop || document.documentElement.scrollTop;
        let height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
        let scrolled = (winScroll / height) * 100;
        document.getElementById("scrollBar").style.width = scrolled + "%";

        // Header Scroll Effect
        const header = document.getElementById("mainHeader");
        if (winScroll > 50) header.classList.add("scrolled");
        else header.classList.remove("scrolled");

        // Back to top visibility
        const btt = document.getElementById("backToTop");
        if (winScroll > 500) btt.classList.add("show");
        else btt.classList.remove("show");

        // Reveal animations on scroll
        document.querySelectorAll('.reveal').forEach(el => {
            let rect = el.getBoundingClientRect();
            if (rect.top < window.innerHeight - 100) el.classList.add('active');
        });
    };

    // Back to top click
    document.getElementById("backToTop").addEventListener("click", () => {
        window.scrollTo({top: 0, behavior: 'smooth'});
    });

    // Reading Time Calculation
    const postBody = document.getElementById("postBody");
    if (postBody) {
        const text = postBody.innerText;
        const wpm = 225;
        const words = text.trim().split(/\s+/).length;
        const time = Math.ceil(words / wpm);
        document.getElementById("readingTime").innerText = time + " min read";
    }

    // Sound Effects System
    const soundContext = new (window.AudioContext || window.webkitAudioContext)();
    function playTone(freq, type, duration) {
        if (!config.soundEnabled) return;
        const osc = soundContext.createOscillator();
        const gain = soundContext.createGain();
        osc.type = type;
        osc.frequency.setValueAtTime(freq, soundContext.currentTime);
        gain.gain.setValueAtTime(0.05, soundContext.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, soundContext.currentTime + duration);
        osc.connect(gain);
        gain.connect(soundContext.destination);
        osc.start();
        osc.stop(soundContext.currentTime + duration);
    }

    document.querySelectorAll('a, button').forEach(el => {
        el.addEventListener('mouseenter', () => playTone(880, 'sine', 0.1));
        el.addEventListener('click', () => playTone(440, 'sine', 0.2));
    });

    document.getElementById('soundToggle').addEventListener('click', function() {
        config.soundEnabled = !config.soundEnabled;
        this.style.color = config.soundEnabled ? 'var(--accent-primary)' : 'var(--text-muted)';
        this.style.borderColor = config.soundEnabled ? 'var(--accent-primary)' : 'var(--glass-border)';
        if (config.soundEnabled && soundContext.state === 'suspended') soundContext.resume();
    });

    // Smart Content Control - Dynamic Post Fetching
    function fetchPosts(label, containerId, title) {
        const container = document.getElementById(containerId);
        if (!container) return;

        const url = `/feeds/posts/default/-/${label}?alt=json-in-script&max-results=${config.postsPerSection}&callback=cb_${label}`;
        const script = document.createElement('script');
        script.src = url;
        document.head.appendChild(script);

        window[`cb_${label}`] = function(json) {
            let html = `<div class="section-title">Explore ${title}</div><div class="card-grid">`;
            if (json.feed.entry) {
                json.feed.entry.forEach(entry => {
                    const link = entry.link.find(l => l.rel === 'alternate').href;
                    const title = entry.title.$t;
                    const snippet = entry.summary ? entry.summary.$t.substring(0, 100) : entry.content.$t.replace(/<[^>]*>/g, '').substring(0, 100);
                    const img = entry.media$thumbnail ? entry.media$thumbnail.url.replace('s72-c', 's600') : '';

                    html += `
                        <a href="${link}" class="post-card">
                            ${img ? `<img src="${img}" class="card-img" loading="lazy" />` : `<div class="card-img skeleton"></div>`}
                            <div class="card-body">
                                <div class="card-tag">${label}</div>
                                <h2 class="card-title">${title}</h2>
                                <p class="card-excerpt">${snippet}...</p>
                                <div class="card-footer">
                                    <span class="read-more">Learn More <svg height="16" viewBox="0 0 24 24" width="16" xmlns="http://www.w3.org/2000/svg"><path d="M12 4l-1.41 1.41L16.17 11H4v2h12.17l-5.58 5.59L12 20l8-8z" fill="currentColor"/></svg></span>
                                </div>
                            </div>
                        </a>
                    `;
                });
            }
            html += `</div>`;
            container.innerHTML += html;
        }
    }

    // Initialize Homepage Sections
    if (window.location.pathname === '/' || window.location.pathname === '/index.html') {
        fetchPosts('Tools', 'dynamic-sections-container', 'AI Tools');
        fetchPosts('Guides', 'dynamic-sections-container', 'Mastery Guides');
        fetchPosts('Earn', 'dynamic-sections-container', 'Profit Strategies');
    }

    // Lazy Loading & Parallax (Lightweight)
    document.addEventListener("DOMContentLoaded", () => {
        const hero = document.querySelector('.hero');
        if (hero) {
            window.addEventListener('scroll', () => {
                let offset = window.pageYOffset;
                hero.style.backgroundPositionY = offset * 0.7 + "px";
            });
        }
    });
//
